#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# Jalankan selalu dari akar repo, apa pun direktori pemanggilnya.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

# URL dashboard Meta; sedapat mungkin menunjuk langsung ke app milik pengguna.
app_root_url() {
  if [[ -n "${META_APP_ID:-}" ]]; then
    printf 'https://developers.facebook.com/apps/%s/' "$META_APP_ID"
  else
    printf 'https://developers.facebook.com/apps/'
  fi
}
app_basic_settings_url() {
  if [[ -n "${META_APP_ID:-}" ]]; then
    printf 'https://developers.facebook.com/apps/%s/settings/basic/' "$META_APP_ID"
  else
    printf 'https://developers.facebook.com/apps/'
  fi
}

banner "Migrasi WhatsApp: Fonnte -> Meta Cloud API"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Cadangkan konfigurasi Fonnte"
say "Migrasi ini menimpa WHATSAPP_API_TOKEN (token Fonnte) dengan token Meta."
say "Kita simpan salinannya dulu supaya Anda bisa kembali kapan saja."
if [[ -f .env.backup-fonnte ]]; then
  note "cadangan sudah ada: .env.backup-fonnte (tidak ditimpa)"
elif [[ -f .env ]]; then
  cp .env .env.backup-fonnte
  note "dibuat: .env.backup-fonnte"
else
  warn "belum ada .env — wizard akan membuatnya dari nol"
fi
note "berkas .env.* diabaikan git, jadi token tidak akan ter-commit"
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Buat Meta App dengan use case WhatsApp"
open_url "https://developers.facebook.com/apps"
step "Klik 'Create App'."
step "Isi App name (mis. MUTAWWIFMU Chatbot) dan email kontak → Next."
step "Pilih use case 'Connect with customers through WhatsApp' → Next."
step "Pilih Business portfolio yang ada, atau buat baru → Next."
step "Lewati daftar publishing requirements (boleh kosong) → Next → Create app."
echo
note "Bila app WhatsApp sudah ada, lewati langkah di atas — cukup buka app itu."
step "Salin App ID dari address bar (angka setelah /apps/)."
ask META_APP_ID "Tempel App ID (Enter bila belum tahu):"
pause

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Hubungkan WABA dan catat Phone Number Id"
open_url "$(app_root_url)"
step "Di bilah sisi kiri klik 'WhatsApp' → 'API Setup'."
step "Bila diminta, hubungkan WhatsApp Business Account atau buat baru."
step "Di dropdown 'From', pilih nomor uji Meta yang tersedia."
step "Salin 'Phone number ID' yang muncul (angka panjang, bukan nomornya)."
ask WHATSAPP_PHONE_NUMBER_ID "Tempel Phone number ID:"
write_env WHATSAPP_PHONE_NUMBER_ID "$WHATSAPP_PHONE_NUMBER_ID"
echo
step "Masih di API Setup: di bagian 'To', tambahkan nomor HP Anda sendiri."
note "Nomor uji Meta hanya boleh mengirim ke maksimal 5 nomor penerima terdaftar."
step "Klik 'Send message', lalu BALAS pesan itu dari HP Anda."
note "Membalas membuka jendela layanan 24 jam — syarat bot boleh membalas nanti."
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Salin App Secret"
open_url "$(app_basic_settings_url)"
step "Buka 'App settings' → 'Basic'."
step "Pada baris 'App secret', klik 'Show', masukkan password Facebook Anda."
step "Salin nilainya."
note "Fungsi: memverifikasi bahwa webhook masuk benar-benar dari Meta (X-Hub-Signature-256)."
ask_secret WHATSAPP_APP_SECRET "Tempel App Secret:"
write_env WHATSAPP_APP_SECRET "$WHATSAPP_APP_SECRET"
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Buat token akses permanen (System User)"
open_url "https://business.facebook.com/latest/settings/system_users"
step "Klik 'Add+' di kanan atas, buat pengguna sistem (mis. mutawwifmu-bot, Admin)."
step "Pilih pengguna sistem itu → klik 'Assign assets'."
note "app Anda → aktifkan 'Manage app' pada Full control"
note "WhatsApp account → aktifkan 'Manage WhatsApp Business accounts' pada Full control"
step "Klik 'Assign assets', lalu klik 'Generate token'."
step "Centang izin: business_management, whatsapp_business_messaging, whatsapp_business_management."
warn "Token hanya ditampilkan sekali. Bila terlewat, buat ulang."
ask_secret WHATSAPP_API_TOKEN "Tempel token:"
write_env WHATSAPP_API_TOKEN "$WHATSAPP_API_TOKEN"
pause

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Tentukan Verify Token webhook"
say "Ini BUKAN nilai dari Meta — Anda yang mengarangnya."
say "Nilai di sini harus SAMA PERSIS dengan yang Anda ketik di dashboard Meta nanti."
note "Enter saja untuk memakai nilai yang sudah ada di .env."
ask WHATSAPP_WEBHOOK_VERIFY_TOKEN "Verify token:"
if [[ -z "$WHATSAPP_WEBHOOK_VERIFY_TOKEN" ]]; then
  warn "verify token kosong — isi minimal 16 karakter acak"
fi
write_env WHATSAPP_WEBHOOK_VERIFY_TOKEN "$WHATSAPP_WEBHOOK_VERIFY_TOKEN"
pause

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Set nomor pengirim, versi Graph API, dan provider"
open_url "$(app_root_url)"
step "Di API Setup, nomor uji tertulis pada dropdown 'From' (mis. +1 555 123 4567)."
ask WHATSAPP_SENDER_NUMBER "Nomor pengirim (boleh pakai + dan spasi):"
write_env WHATSAPP_SENDER_NUMBER "$WHATSAPP_SENDER_NUMBER"
echo
ask WHATSAPP_API_BASE_URL "Versi Graph API:"
if [[ -z "$WHATSAPP_API_BASE_URL" ]]; then
  WHATSAPP_API_BASE_URL="https://graph.facebook.com/v26.0"
fi
write_env WHATSAPP_API_BASE_URL "$WHATSAPP_API_BASE_URL"
write_env WHATSAPP_PROVIDER "whatsapp-cloud-api"
echo
if [[ -z "$(_existing WHATSAPP_ADMIN_NUMBER || true)" ]]; then
  warn "WHATSAPP_ADMIN_NUMBER belum diisi — handoff ke admin tidak akan bekerja."
  step "Isi nomor WhatsApp admin penerima handoff (E.164), mis. +62 822 8388 6627."
  ask WHATSAPP_ADMIN_NUMBER "Nomor admin:"
  write_env WHATSAPP_ADMIN_NUMBER "$WHATSAPP_ADMIN_NUMBER"
else
  note "WHATSAPP_ADMIN_NUMBER sudah terisi — dibiarkan apa adanya."
fi
pause

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Periksa konfigurasi"
say "Menjalankan npm run cutover:check..."
echo
npm run cutover:check 2>&1 | sed 's/^/  /' || true
echo
note "Bila masih 'belum siap', perbaiki baris [GAGAL] lewat stage sebelumnya (jalankan ulang wizard)."
echo

# Uji nyata ke Graph API: menangkap Phone Number Id salah atau token kurang izin
# sebelum sampai ke tahap webhook, tempat gejalanya jauh lebih membingungkan.
if [[ -n "$WHATSAPP_PHONE_NUMBER_ID" && -n "$WHATSAPP_API_TOKEN" ]]; then
  say "Menguji kredensial langsung ke Graph API..."
  API_HASIL=$(node -e '
const [base, id, token] = process.argv.slice(1);
const url = base.replace(/\/+$/, "") + "/" + encodeURIComponent(id) +
  "?fields=display_phone_number,verified_name";
fetch(url, { headers: { authorization: "Bearer " + token }, signal: AbortSignal.timeout(15000) })
  .then(async (r) => {
    const t = (await r.text()).trim();
    if (r.ok) console.log("OK " + t.slice(0, 200));
    else console.log("GAGAL status=" + r.status + " " + t.slice(0, 240));
  })
  .catch((e) => console.log("GAGAL koneksi: " + (e && e.message ? e.message : e)));
' "$WHATSAPP_API_BASE_URL" "$WHATSAPP_PHONE_NUMBER_ID" "$WHATSAPP_API_TOKEN" 2>&1) || API_HASIL="GAGAL wizard gagal menjalankan pemeriksaan"

  if [[ "$API_HASIL" == OK* ]]; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "token dan Phone Number Id diterima Graph API"
    note "${API_HASIL#OK }"
  else
    warn "$API_HASIL"
    note "kode 190 / 'Invalid OAuth' → token salah, kedaluwarsa, atau tersalin tidak utuh"
    note "kode 200 / 'does not have permission' → izin token kurang; buat ulang dengan 3 izin di stage 5"
    note "kode 100 / 'Unsupported get request' → Phone Number Id salah (itu ID, bukan nomornya)"
    note "HTTP 404 / 'Unsupported version' → versi Graph API di WHATSAPP_API_BASE_URL tidak berlaku"
  fi
  echo

  # Kesehatan token: token sementara dari dashboard mudah tertukar dengan token
  # system user permanen. Bot 24/7 akan berhenti membalas tanpa gejala saat
  # token sementara itu kedaluwarsa.
  say "Memeriksa masa berlaku dan izin token..."
  TOKEN_HASIL=$(node -e '
const [base, token] = process.argv.slice(1);
const url = base.replace(/\/+$/, "") + "/debug_token?input_token=" +
  encodeURIComponent(token) + "&access_token=" + encodeURIComponent(token);
fetch(url, { signal: AbortSignal.timeout(15000) })
  .then(async (r) => {
    const j = await r.json();
    if (j.error) return console.log("GAGAL " + JSON.stringify(j.error).slice(0, 200));
    const d = j.data || {};
    const perlu = ["business_management", "whatsapp_business_messaging", "whatsapp_business_management"];
    const kurang = perlu.filter((p) => !(d.scopes || []).includes(p));
    const permanen = d.expires_at === 0;
    console.log("TIPE=" + d.type + " PERMANEN=" + permanen +
      " KEDALUWARSA=" + (permanen ? "-" : new Date(d.expires_at * 1000).toISOString()) +
      " KURANG=" + (kurang.join(",") || "-"));
  })
  .catch((e) => console.log("GAGAL koneksi: " + (e && e.message ? e.message : e)));
' "$WHATSAPP_API_BASE_URL" "$WHATSAPP_API_TOKEN" 2>&1) || TOKEN_HASIL="GAGAL wizard gagal menjalankan pemeriksaan"

  if [[ "$TOKEN_HASIL" == TIPE=* ]]; then
    note "$TOKEN_HASIL"
    if [[ "$TOKEN_HASIL" != *"PERMANEN=true"* ]]; then
      warn "token ini BUKAN permanen — kemungkinan token sementara dashboard, bukan token System User."
      note "Bot 24/7 akan berhenti membalas begitu token kedaluwarsa. Buat ulang lewat stage 5."
    fi
    if [[ "$TOKEN_HASIL" == *"TIPE=USER"* ]]; then
      warn "tipe token USER — seharusnya SYSTEM_USER untuk bot yang berjalan sendiri."
    fi
    if [[ "$TOKEN_HASIL" != *"KURANG=- "* && "$TOKEN_HASIL" != *"KURANG=-"* ]]; then
      warn "izin token kurang lengkap — buat ulang dengan ketiga izin di stage 5."
    fi
  else
    warn "$TOKEN_HASIL"
  fi
  echo
fi
pause

# ── Stage 9 ───────────────────────────────────────────────────────────────
stage "Jalankan bot dan tunnel publik"
say "Buka DUA terminal baru. Biarkan wizard ini tetap terbuka."
echo
step "Terminal A:   npm start"
step "Terminal B:   ngrok http 3000"
