ask META_PUBLIC_BASE_URL "Tempel URL HTTPS publik:"
while [[ -n "$META_PUBLIC_BASE_URL" && "$META_PUBLIC_BASE_URL" != https://* ]]; do
  warn "URL harus dimulai dengan https:// — coba lagi."
  ask META_PUBLIC_BASE_URL "Tempel URL HTTPS publik:"
done
if [[ -z "$META_PUBLIC_BASE_URL" ]]; then
  warn "URL kosong — handshake tidak dapat diverifikasi otomatis; lanjutkan manual di stage berikutnya."
fi
pause

# ── Stage 10 ──────────────────────────────────────────────────────────────
stage "Daftarkan webhook di Meta dan subscribe field messages"
open_url "$(app_root_url)"
step "Klik 'WhatsApp' → 'Configuration'."
step "Pada bagian 'Webhook', klik 'Edit'."
echo
say "  Callback URL : ${META_PUBLIC_BASE_URL}/webhook"
say "  Verify token : <nilai WHATSAPP_WEBHOOK_VERIFY_TOKEN Anda>"
echo
step "Klik 'Verify and save'. Meta akan memanggil bot Anda saat itu juga."
step "Setelah tersimpan, klik 'Manage' di samping field webhook."
step "SUBSCRIBE field 'messages'."
warn "Verify dan subscribe adalah DUA aksi terpisah — tanpa subscribe, bot akan diam."
pause "Sudah klik 'Verify and save'?"

if [[ -n "$META_PUBLIC_BASE_URL" && -n "$WHATSAPP_WEBHOOK_VERIFY_TOKEN" ]]; then
  echo
  say "Memverifikasi handshake dari sisi wizard (bot + tunnel harus masih hidup)..."
  HASIL=$(node -e '
const [base, token] = process.argv.slice(1);
const url = base.replace(/\/+$/, "") +
  "/webhook?hub.mode=subscribe&hub.challenge=ping12345&hub.verify_token=" + encodeURIComponent(token);
fetch(url, { signal: AbortSignal.timeout(15000) })
  .then(async (r) => {
    const t = (await r.text()).trim();
    if (r.status === 200 && t === "ping12345") console.log("OK handshake berhasil");
    else console.log("GAGAL status=" + r.status + " badan=" + t.slice(0, 120));
  })
  .catch((e) => console.log("GAGAL koneksi: " + (e && e.message ? e.message : e)));
' "$META_PUBLIC_BASE_URL" "$WHATSAPP_WEBHOOK_VERIFY_TOKEN" 2>&1) || HASIL="GAGAL wizard gagal menjalankan pemeriksaan"

  if [[ "$HASIL" == OK* ]]; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "handshake berhasil — bot membalas challenge Meta dengan benar"
  else
    warn "$HASIL"
    note "cek: bot jalan dengan provider whatsapp-cloud-api? tunnel masih hidup?"
    note "cek: verify token di .env sama persis dengan yang diketik di dashboard?"
  fi
fi
pause

